actionConfiguration.body:
function (nowV, startV, durV, roomId) {
  const res = (available, reasonCode, message) => ({
    available,
    reasonCode,
    message
  });
  const room = Rules.rooms.find(r => r.id === roomId);
  if (!room) return res(false, "INVALID_ROOM", "Select a room.");
  const now = Rules.toInt(nowV), start = Rules.toInt(startV), dur = Rules.toInt(durV);
  if (now === null || start === null || dur === null) return res(false, "INVALID_TIME", "Enter whole minutes (0-1440) in every field.");
  const end = start + dur;
  if (now > 1440 || dur <= 0 || end > 1440) return res(false, "INVALID_TIME", "Duration must be greater than 0 and the slot must end by 1440.");
  if (start <= now) return res(false, "PAST_TIME", "Start time must be after the current time (" + now + ").");
  if (room.blocked) return res(false, "BLOCKED", "Room " + room.id + " is blocked.");
  if (dur > 120) return res(false, "TOO_LONG", "Maximum duration is 120 minutes (requested " + dur + ").");
  const hit = room.bookings.find(b => start < b.end && b.start < end);
  if (hit) return res(false, "OVERLAP", "Overlaps existing booking " + hit.start + "-" + hit.end + ".");
  return res(true, "AVAILABLE", "Room " + room.id + " is free from " + start + " to " + end + ".");
}

