  rooms: [
    { id: "A101", name: "Seminar Room A101", blocked: false, bookings: [{ start: 600, end: 660 }] },
    { id: "A102", name: "Computer Lab A102", blocked: false, bookings: [{ start: 720, end: 780 }, { start: 900, end: 960 }] },
    { id: "B201", name: "Meeting Room B201", blocked: false, bookings: [{ start: 630, end: 690 }] },
    { id: "B202", name: "Lecture Hall B202", blocked: true, bookings: [] },
    { id: "C301", name: "Video Studio C301", blocked: false, bookings: [{ start: 660, end: 780 }] }
  ],
  roomOptions() {
    return this.rooms.map(r => ({ name: r.name + (r.blocked ? " (blocked)" : ""), code: r.id }));
  },
  bookingsFor(roomId) {
    const room = this.rooms.find(r => r.id === roomId);
    return room ? room.bookings.map((b, i) => ({ room: room.id, booking: i + 1, start: b.start, end: b.end })) : [];
  },
