    const s = String(v ?? "").trim();
    return /^\d+$/.test(s) ? Number(s) : null;
  },
  // Validation -> blocked -> duration -> overlap (same order as checkAvailability)
  check(nowV, startV, durV, roomId) {
    const res = (available, reasonCode, message) => ({ available, reasonCode, message });
    const room = this.rooms.find(r => r.id === roomId);
    if (!room) return res(false, "INVALID_ROOM", "Select a room.");
