      return res(false, "INVALID_TIME", "Duration must be greater than 0 and the slot must end by 1440.");
    if (start <= now)
      return res(false, "PAST_TIME", "Start time must be after the current time (" + now + ").");
    if (room.blocked)
      return res(false, "BLOCKED", "Room " + room.id + " is blocked.");
    if (dur > 120)
      return res(false, "TOO_LONG", "Maximum duration is 120 minutes (requested " + dur + ").");
    const hit = room.bookings.find(b => start < b.end && b.start < end);
    if (hit)
      return res(false, "OVERLAP", "Overlaps existing booking " + hit.start + "-" + hit.end + ".");
    return res(true, "AVAILABLE", "Room " + room.id + " is free from " + start + " to " + end + ".");
  },
  async run() {
    const r = this.check(InputNow.text, InputStart.text, InputDuration.text, SelectRoom.selectedOptionValue);
    await storeValue("checkResult", r, false); // in-memory only: no stale result after reload
    return r;
  }
}

